import {gasSyringe} from './gas-syringe-art.js';
const reagents={peroxide:{agent:'過氧化氫',formula:'H₂O₂'},chlorine:{agent:'次氯酸鈉',formula:'NaClO'},vitaminc:{agent:'維生素 C 溶液',formula:'維生素 C'},sulfur:{agent:'二氧化硫',formula:'SO₂'}};
export function laboratoryReagent(key,suffix='supply'){const d=reagents[key];if(key!=='sulfur')return `<svg class="bleach-supply bleach-beaker" viewBox="0 0 120 120" aria-hidden="true"><defs><linearGradient id="liquid-${key}-${suffix}-glass"><stop stop-color="#e9fbff" stop-opacity=".75"/><stop offset=".3" stop-color="#fff" stop-opacity=".18"/><stop offset=".8" stop-color="#91b5be" stop-opacity=".35"/><stop offset="1" stop-color="#f5ffff" stop-opacity=".8"/></linearGradient><linearGradient id="liquid-${key}-${suffix}-liquid" x2="0" y2="1"><stop stop-color="#deeff1" stop-opacity=".6"/><stop offset="1" stop-color="#b1d6df" stop-opacity=".75"/></linearGradient></defs><ellipse cx="60" cy="109" rx="42" ry="6" fill="#26495324"/><path d="M23 19L18 14H95L91 20V98Q91 109 60 109T27 98V24Z" fill="url(#liquid-${key}-${suffix}-glass)" stroke="#7c9ea8" stroke-width="1.8"/><path d="M29 60H89V97Q89 106 60 106T29 97Z" fill="url(#liquid-${key}-${suffix}-liquid)"/><ellipse cx="59" cy="60" rx="30" ry="4" fill="#eefcff" fill-opacity=".8" stroke="#a0c5cc"/><path d="M34 28V92M87 30V93" stroke="#fff" stroke-width="3" stroke-linecap="round" opacity=".85"/><path d="M70 35H83M75 45H83M70 55H83M75 65H83M70 75H83M75 85H83" stroke="#668c96" stroke-width="1.2"/><rect x="34" y="71" width="36" height="22" rx="3" fill="#fffdf0" fill-opacity=".94"/><text x="52" y="86" text-anchor="middle" fill="#315560" font-size="11">${d.formula}</text><path d="M24 19Q60 24 93 18" fill="none" stroke="#fff" stroke-width="2"/></svg><strong>${key==='vitaminc'?d.agent:d.agent+' '+d.formula}</strong>`;
return gasSyringe(suffix);}
export function laboratoryTransfer(key){return '<div class="lab-reagent-transfer '+(key==='sulfur'?'gas-transfer':'liquid-transfer')+'" aria-hidden="true">'+laboratoryReagent(key,'transfer')+'<i></i></div>';}
